import{_ as t,o as a,c as s,a2 as n}from"./chunks/framework.9yf7n3zg.js";const o="/guide/media/updates-settings.webp",u=JSON.parse('{"title":"Updates and uninstalling","description":"","frontmatter":{},"headers":[],"relativePath":"reference/updates.md","filePath":"reference/updates.md","lastUpdated":1792685126000}'),r={name:"reference/updates.md"};function i(d,e,h,l,c,p){return a(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="updates-and-uninstalling" tabindex="-1">Updates and uninstalling <a class="header-anchor" href="#updates-and-uninstalling" aria-label="Permalink to &quot;Updates and uninstalling&quot;">​</a></h1><p>Leathercase does not update itself behind your back. It asks whether a newer version exists only when you say so, downloads it only when you take it, and installs it when you restart. This page covers how that works on each system, where to read what changed, and how to uninstall the app, including what stays behind.</p><h2 id="checking-for-a-newer-version" tabindex="-1">Checking for a newer version <a class="header-anchor" href="#checking-for-a-newer-version" aria-label="Permalink to &quot;Checking for a newer version&quot;">​</a></h2><p>Nothing goes online until you ask. A fresh install has never checked, and <strong>Check when Leathercase opens</strong> is off.</p><p><img src="'+o+`" alt="Settings at Updates: This version, Check when Leathercase opens switched off, the Newer version row saying Not checked since Leathercase opened with Check now, and Uninstall with How to uninstall" width="860" height="615" loading="lazy"></p><p>You can check in four ways:</p><ul><li><strong>Settings</strong>, <strong>Updates</strong>, <strong>Check now</strong>. Open Settings with <code>Ctrl+,</code> (<code>Cmd+,</code> on macOS) or from <strong>Settings</strong> at the foot of the sidebar.</li><li><strong>Settings</strong>, <strong>About</strong>, <strong>Check now</strong>. About Leathercase shows this copy&#39;s version with the same row as Updates; open it from the <strong>Leathercase</strong> menu on macOS, from <strong>Help</strong> on Windows and Linux, or with <strong>About Leathercase</strong> in the find field.</li><li>The <strong>File</strong> menu, <strong>Check for updates</strong>.</li><li>The find field: press <code>Ctrl+K</code> (<code>Cmd+K</code>), type &quot;Check for updates&quot; and press <code>Enter</code>.</li></ul><p>Or let Leathercase check each time it opens: turn on <strong>Check when Leathercase opens</strong> in <strong>Settings</strong>, <strong>Updates</strong>. The hint says what that does: <strong>Off until you turn it on. When a newer version is out, a dot on Settings says so; nothing downloads by itself.</strong> The choice is this computer&#39;s, kept in its preferences.</p><p>When a check finds a newer version, a dot appears on <strong>Settings</strong> in the sidebar and on <strong>Updates</strong> in the Settings list, both saying <strong>Version 0.25.0 is out</strong> (with the real number).</p><h2 id="the-updates-page" tabindex="-1">The Updates page <a class="header-anchor" href="#the-updates-page" aria-label="Permalink to &quot;The Updates page&quot;">​</a></h2><p>The page opens with one line: <strong>Leathercase goes online for one thing only, to ask which version is newest, and only when you say so. Nothing about you or your writing is sent.</strong> Then four rows.</p><table tabindex="0"><thead><tr><th>Row</th><th>What it shows</th></tr></thead><tbody><tr><td><strong>This version</strong></td><td>The version installed on this computer</td></tr><tr><td><strong>Check when Leathercase opens</strong></td><td>The switch described above</td></tr><tr><td><strong>Newer version</strong></td><td>What the last check found, and the one thing you can do next</td></tr><tr><td><strong>Uninstall</strong></td><td><strong>How to uninstall</strong> opens the uninstall guide inside the app; <strong>Back to Settings</strong> returns</td></tr></tbody></table><p>The <strong>Newer version</strong> row moves through these states:</p><table tabindex="0"><thead><tr><th>The row says</th><th>The button</th><th>What happens</th></tr></thead><tbody><tr><td><strong>Not checked since Leathercase opened.</strong></td><td><strong>Check now</strong></td><td>Asks the releases which version is newest</td></tr><tr><td><strong>Asking the releases…</strong></td><td>none</td><td>The check is running</td></tr><tr><td><strong>This is the newest version. Checked at 14:05 UTC.</strong></td><td><strong>Check again</strong></td><td>Nothing to do</td></tr><tr><td><strong>Version 0.25.0 is out. It downloads now and installs when you restart.</strong></td><td><strong>Download</strong></td><td>Downloads the new version in the background</td></tr><tr><td><strong>Version 0.25.0 is out. This copy cannot replace itself, so its download page opens.</strong></td><td><strong>Open download page</strong></td><td>Opens the version&#39;s page in your browser, where you download the installer</td></tr><tr><td><strong>Downloading version 0.25.0…</strong></td><td>none</td><td>The download is running</td></tr><tr><td><strong>Version 0.25.0 is downloaded. It installs when you restart, or the next time you quit.</strong></td><td><strong>Restart now</strong></td><td>Quits, installs and opens the new version</td></tr><tr><td><strong>Leathercase could not reach its releases. Check the connection and try again.</strong></td><td><strong>Try again</strong></td><td>The check or the download failed; nothing changed</td></tr><tr><td><strong>This copy of Leathercase cannot check for updates. Newer versions are on the download page.</strong></td><td><strong>Try again</strong></td><td>This kind of install has no update feed</td></tr><tr><td><strong>A build run from source does not check.</strong></td><td>none</td><td>Only for a copy built by hand from the source</td></tr></tbody></table><p>A downloaded update waits. Keep working; it installs when you choose <strong>Restart now</strong>, or by itself the next time you quit Leathercase. Either way Leathercase first finishes what it was writing (the sentence log, the mate&#39;s state, your preferences), waiting at most two seconds, and then quits.</p><h2 id="on-each-system" tabindex="-1">On each system <a class="header-anchor" href="#on-each-system" aria-label="Permalink to &quot;On each system&quot;">​</a></h2><table tabindex="0"><thead><tr><th>System and package</th><th>What <strong>Download</strong> does</th></tr></thead><tbody><tr><td>Windows (the <code>.exe</code> installer)</td><td>Downloads the new version and installs it on restart, from a version before 0.30 too</td></tr><tr><td>macOS (the <code>.dmg</code>)</td><td>Downloads the new version and replaces the app on restart. Every release is signed with the same Apple Developer ID and notarised by Apple, which is what lets the app replace itself. Once only, going from a version before 0.30 to 0.30 or later needs a download by hand: the app&#39;s identity changed with its name, so the old app cannot replace itself with the new one. Your homes and settings carry over</td></tr><tr><td>Linux, AppImage</td><td>Downloads the new AppImage and replaces the old one on restart</td></tr><tr><td>Linux, <code>.deb</code></td><td>The app cannot replace a package your system installed, so <strong>Open download page</strong> opens the release instead. Download the new <code>.deb</code> and install it as you installed the first, from your software centre or with <code>sudo apt install ./leathercase-…amd64.deb</code></td></tr></tbody></table><p>The updater&#39;s downloads are kept in a cache folder of their own (see <a href="#uninstalling">Uninstalling</a>) and do not touch your writing home.</p><h2 id="installing-a-new-version-by-hand" tabindex="-1">Installing a new version by hand <a class="header-anchor" href="#installing-a-new-version-by-hand" aria-label="Permalink to &quot;Installing a new version by hand&quot;">​</a></h2><p>Every release is on the <a href="https://github.com/Leathercase/leathercase-releases/releases/latest" target="_blank" rel="noreferrer">releases page</a>. Download the file for your system and install it over the old version; your homes, preferences and stories stay as they were, since none of them live inside the app.</p><table tabindex="0"><thead><tr><th>System</th><th>File</th></tr></thead><tbody><tr><td>Windows (x64 and Arm)</td><td><code>leathercase-&lt;version&gt;-win.exe</code></td></tr><tr><td>macOS, Apple silicon</td><td><code>leathercase-&lt;version&gt;-mac-arm64.dmg</code></td></tr><tr><td>macOS, Intel</td><td><code>leathercase-&lt;version&gt;-mac-x64.dmg</code></td></tr><tr><td>Linux, x86_64</td><td><code>leathercase-&lt;version&gt;-linux-x86_64.AppImage</code> or <code>leathercase-&lt;version&gt;-linux-amd64.deb</code></td></tr><tr><td>Linux, Arm</td><td><code>leathercase-&lt;version&gt;-linux-arm64.AppImage</code> or <code>leathercase-&lt;version&gt;-linux-arm64.deb</code></td></tr></tbody></table><p>Each release also lists a <code>SHA256SUMS</code> file per system, so you can check that the file you downloaded is the one published.</p><div class="info custom-block"><p class="custom-block-title">Windows asks before the installer runs</p><p>The Windows installer is not yet signed, so Windows SmartScreen may say it &quot;protected your PC&quot;. Choose <strong>More info</strong>, then <strong>Run anyway</strong>. The macOS app is signed and notarised and opens without a warning on macOS 12 or later.</p></div><h2 id="what-changed-in-a-version" tabindex="-1">What changed in a version <a class="header-anchor" href="#what-changed-in-a-version" aria-label="Permalink to &quot;What changed in a version&quot;">​</a></h2><p>Each release on the <a href="https://github.com/Leathercase/leathercase-releases/releases" target="_blank" rel="noreferrer">releases page</a> carries its notes: what changed in that version, followed by a table of which file to download. The app does not show release notes itself; <strong>Every version and its notes</strong>, on <strong>Settings</strong>, <strong>About</strong>, opens the releases page in your browser, as does <strong>Open download page</strong>.</p><h2 id="uninstalling" tabindex="-1">Uninstalling <a class="header-anchor" href="#uninstalling" aria-label="Permalink to &quot;Uninstalling&quot;">​</a></h2><p>Uninstalling removes the app. It never touches your writing: your notes stay where they are, and so do the files Leathercase kept beside them, so you can read them without the app or open them again after a reinstall. The same guide is in the app: <strong>Settings</strong>, <strong>Updates</strong>, <strong>How to uninstall</strong>.</p><h3 id="before-you-uninstall-leathercase-s-files-in-your-homes" tabindex="-1">Before you uninstall: Leathercase&#39;s files in your homes <a class="header-anchor" href="#before-you-uninstall-leathercase-s-files-in-your-homes" aria-label="Permalink to &quot;Before you uninstall: Leathercase&#39;s files in your homes&quot;">​</a></h3><p>Leathercase keeps its own files in each writing home: <code>Suite.md</code> and <code>suite/</code> at its root, <code>Writer/</code> for your cards, and a <code>suite/</code> folder inside each story&#39;s folder (see <a href="/guide/reference/suite-files">Files Leathercase writes</a>). Uninstalling leaves them, on purpose: they are yours, and they hold your grid, threads, cards and comments.</p><p>To remove them too, do it while the app is still installed: in <strong>Settings</strong>, <strong>Storage</strong>, choose <strong>Remove…</strong> beside each home, then <strong>Purge</strong>. Purge moves Leathercase&#39;s files to the trash and leaves your notes alone. Or delete those folders yourself at any time.</p><p>If you connected an agent, remove the Leathercase bridge from that agent&#39;s app as well: in Claude Desktop, under Settings, Extensions; for the others, the line you added to their settings (see <a href="/guide/guide/connect-an-agent">Connect an agent</a>).</p><h3 id="windows" tabindex="-1">Windows <a class="header-anchor" href="#windows" aria-label="Permalink to &quot;Windows&quot;">​</a></h3><ol><li>Quit Leathercase.</li><li>Open Settings, Apps, Installed apps. Find Leathercase, open its menu, and choose Uninstall. On older Windows, open Control Panel, Programs and Features.</li><li>The uninstaller asks whether to remove this computer&#39;s settings as well. Answer Yes to remove them; answer No to keep them for a later reinstall.</li></ol><p>This computer&#39;s settings are the list of your homes, your preferences, connected agents and the downloaded search model. They live in <code>%APPDATA%\\Leathercase</code>. The uninstaller also removes the <code>leathercase://</code> link and the updater&#39;s downloads in <code>%LOCALAPPDATA%\\@leathercasedesktop-updater</code>.</p><p>When Leathercase was installed for all users and Windows asked another account, an administrator, to approve the uninstall, the uninstaller works in that administrator&#39;s account. Its question then removes that account&#39;s settings, not yours, and your link stays registered. To remove your settings, sign in to your own account and delete <code>%APPDATA%\\Leathercase</code> yourself.</p><p>To uninstall without questions, as an administrator would, run the uninstaller with <code>/S</code>; add <code>--delete-app-data</code> to remove this computer&#39;s settings too. This is where it is when Leathercase was installed for you alone in the default place; otherwise it is in the folder you chose:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;%LOCALAPPDATA%\\Programs\\leathercase\\Uninstall leathercase.exe&quot; /S --delete-app-data</span></span></code></pre></div><p>A Leathercase updated from a version before 0.30 stays in the folder it was first installed in, <code>%LOCALAPPDATA%\\Programs\\creative-suite</code>, and its uninstaller is there.</p><h3 id="macos" tabindex="-1">macOS <a class="header-anchor" href="#macos" aria-label="Permalink to &quot;macOS&quot;">​</a></h3><p>macOS apps have no uninstaller.</p><ol><li>Quit Leathercase.</li><li>In Finder, open Applications and drag Leathercase to the Trash. Empty the Trash.</li></ol><p>The app&#39;s settings stay behind in your Library folder. To remove them too, in Finder choose Go, Go to Folder, and delete each of these that exists:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>~/Library/Application Support/Leathercase</span></span>
<span class="line"><span>~/Library/Caches/@leathercasedesktop-updater</span></span>
<span class="line"><span>~/Library/Caches/app.leathercase.desktop</span></span>
<span class="line"><span>~/Library/Caches/app.leathercase.desktop.ShipIt</span></span>
<span class="line"><span>~/Library/HTTPStorages/app.leathercase.desktop</span></span>
<span class="line"><span>~/Library/Preferences/app.leathercase.desktop.plist</span></span>
<span class="line"><span>~/Library/Saved Application State/app.leathercase.desktop.savedState</span></span></code></pre></div><p>Or in Terminal:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>rm -rf ~/Library/Application\\ Support/Leathercase ~/Library/Caches/@leathercasedesktop-updater ~/Library/Caches/app.leathercase.desktop* ~/Library/HTTPStorages/app.leathercase.desktop ~/Library/Preferences/app.leathercase.desktop.plist ~/Library/Saved\\ Application\\ State/app.leathercase.desktop.savedState</span></span></code></pre></div><h3 id="linux" tabindex="-1">Linux <a class="header-anchor" href="#linux" aria-label="Permalink to &quot;Linux&quot;">​</a></h3><p>How you remove the app depends on how you installed it.</p><p>If you installed the <code>.deb</code> package (Debian, Ubuntu, Mint, Pop!_OS), remove it from your software centre, or from a terminal:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo apt remove leathercase</span></span></code></pre></div><p>If you run the AppImage, it was never installed: delete the <code>.AppImage</code> file. If a tool such as Gear Lever or AppImageLauncher added it to your menu, remove it there as well.</p><p>The AppImage adds two files the first time it runs, so <code>leathercase://</code> links reach it: a menu entry and its icon. Delete them with the AppImage:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>rm -f ~/.local/share/applications/leathercase.desktop ~/.local/share/icons/hicolor/512x512/apps/leathercase.png</span></span></code></pre></div><p>Either way, the app&#39;s settings stay behind. To remove them too:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>rm -rf ~/.config/Leathercase ~/.cache/@leathercasedesktop-updater</span></span></code></pre></div><h3 id="what-versions-before-0-30-left-behind" tabindex="-1">What versions before 0.30 left behind <a class="header-anchor" href="#what-versions-before-0-30-left-behind" aria-label="Permalink to &quot;What versions before 0.30 left behind&quot;">​</a></h3><p>Before 0.30 the app had another name, and it kept its settings in other folders. Leathercase moves the settings to its own folder the first time it opens, so what is left in the old places can go. On Windows and Linux, 0.30 arrived as an ordinary update; on macOS it had to be downloaded once by hand, because the app&#39;s identity changed with its name, so the old app may still be in Applications.</p><p>On Windows, delete <code>%APPDATA%\\@creative-suite</code> and <code>%LOCALAPPDATA%\\@creative-suitedesktop-updater</code> if they are still there.</p><p>On macOS, in Terminal:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>rm -rf ~/Library/Application\\ Support/@creative-suite ~/Library/Caches/@creative-suitedesktop-updater ~/Library/Caches/com.creativesuite.desktop* ~/Library/HTTPStorages/com.creativesuite.desktop ~/Library/Preferences/com.creativesuite.desktop.plist ~/Library/Saved\\ Application\\ State/com.creativesuite.desktop.savedState</span></span></code></pre></div><p>On Linux, the <code>.deb</code> of 0.30 replaces the old package. The old AppImage&#39;s menu entry and its settings can go:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>rm -f ~/.local/share/applications/creative-suite.desktop ~/.local/share/icons/hicolor/512x512/apps/creative-suite.png</span></span>
<span class="line"><span>rm -rf ~/.config/@creative-suite ~/.cache/@creative-suitedesktop-updater</span></span></code></pre></div><h3 id="what-stays-behind" tabindex="-1">What stays behind <a class="header-anchor" href="#what-stays-behind" aria-label="Permalink to &quot;What stays behind&quot;">​</a></h3><table tabindex="0"><thead><tr><th>What</th><th>Where</th><th>Removed by uninstalling</th></tr></thead><tbody><tr><td>Your manuscripts and notes</td><td>Your writing homes</td><td>Never</td></tr><tr><td>Leathercase&#39;s files for your stories: <code>Suite.md</code>, <code>suite/</code>, <code>Writer/</code></td><td>Your writing homes</td><td>Never; <strong>Purge</strong> them first, or delete them by hand</td></tr><tr><td>This computer&#39;s settings: homes list, preferences, keys, agents, the meaning search model, the sample copy</td><td>The app&#39;s data folder</td><td>On Windows if you answer Yes; on macOS and Linux delete it by hand</td></tr><tr><td>Downloaded updates</td><td>The updater&#39;s cache folder</td><td>On Windows; on macOS and Linux delete it by hand</td></tr><tr><td>The <code>leathercase://</code> link</td><td>Windows registry; macOS app; Linux menu entry</td><td>With the app; for the AppImage, delete the menu entry by hand</td></tr><tr><td>The bridge in an agent&#39;s app</td><td>Claude Desktop, Codex, Cursor and the others</td><td>Never; remove it in that app</td></tr><tr><td>Files you exported</td><td>Wherever you saved them</td><td>Never</td></tr></tbody></table><p>Reinstalling later picks up whatever you kept: a writing home whose <code>suite/</code> folders are still there opens with its stories, grid and cards as you left them, on this computer or any other.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="/guide/reference/suite-files">Files Leathercase writes</a></li><li><a href="/guide/reference/privacy">Privacy</a></li><li><a href="/guide/guide/homes-and-stories">Homes and stories</a></li><li><a href="/guide/guide/connect-an-agent">Connect an agent</a></li></ul>`,66)])])}const m=t(r,[["render",i]]);export{u as __pageData,m as default};
